def f(g):
    comps=components(g)
    from collections import Counter
    cnt=Counter(c for c,_ in comps); cells=Counter()
    first={}
    for idx,(c,comp) in enumerate(comps):
        cells[c]+=len(comp); first.setdefault(c,idx)
    twins={}
    for c,comp in comps: twins.setdefault((c,norm(comp)),[]).append(comp)
    # cross-color twins by identical normalized form
    form={}
    for c,comp in comps: form.setdefault(norm(comp),[]).append((c,comp))
    maxc=max(cnt,key=lambda c:(cnt[c],-first[c]))
    minc=min(cnt,key=lambda c:(cnt[c],cells[c],first[c]))
    # source shape: shape of maxc that has a twin (same form, another shape)
    src=None
    for c,comp in comps:
        if c==maxc and len(form[norm(comp)])>1: src=comp; break
    out=[row[:] for row in g]
    if src:
        for y,x in src: out[y][x]=minc
    return out
