from collections import Counter
def f(g):
    comps=components(g)
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    comps=[(c,comp) for c,comp in comps if c!=bg]
    cnt=Counter(c for c,_ in comps); cells=Counter(); first={}
    for idx,(c,comp) in enumerate(comps):
        cells[c]+=len(comp); first.setdefault(c,idx)
    form={}
    for c,comp in comps: form.setdefault(norm(comp),[]).append((c,comp))
    maxc=max(cnt,key=lambda c:(cnt[c],-first[c]))
    minc=min(cnt,key=lambda c:(cnt[c],cells[c],first[c]))
    out=[row[:] for row in g]
    for c,comp in comps:
        if c==maxc and len(form[norm(comp)])>1:
            for y,x in comp: out[y][x]=minc
            break
    return out
